SELECT 'batch_031_ddf53069_wav_13' AS batch_id,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-upload-26c13d22-002','sm-upload-64d8dc24-596','sm-upload-67b27f56-b5b','sm-upload-6a01492c-ebe','sm-upload-74718096-633','sm-upload-831d9eee-6f0','sm-upload-986e39a0-94d','sm-upload-aa969a9a-7db','sm-upload-b831ca53-608','sm-upload-bbb56a95-410','sm-upload-db5279a1-e00','sm-upload-e327ba41-cf6','sm-upload-eba9f299-c67') AND album_id='al-cfe9a2e735c7900a5b0e96f5ddf53069') AS candidate_masters_in_target,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-upload-26c13d22-002','sm-upload-64d8dc24-596','sm-upload-67b27f56-b5b','sm-upload-6a01492c-ebe','sm-upload-74718096-633','sm-upload-831d9eee-6f0','sm-upload-986e39a0-94d','sm-upload-aa969a9a-7db','sm-upload-b831ca53-608','sm-upload-bbb56a95-410','sm-upload-db5279a1-e00','sm-upload-e327ba41-cf6','sm-upload-eba9f299-c67') AND album_id='pending-uploads') AS candidate_masters_still_pending,(SELECT COUNT(*) FROM albums WHERE id='al-cfe9a2e735c7900a5b0e96f5ddf53069' AND name='Still With U') AS target_album_rows,(SELECT song_count FROM albums WHERE id='al-cfe9a2e735c7900a5b0e96f5ddf53069') AS stored_song_count,(SELECT COALESCE(SUM(si.size),0) FROM song_instances si JOIN song_masters sm ON sm.id=si.master_id WHERE sm.album_id='al-cfe9a2e735c7900a5b0e96f5ddf53069') AS calculated_size;
